import{j as e}from"./vendor-DJcWBMKH.js";import{H as t,I as o,F as a}from"./FAQAccordion-D7QwrsAR.js";import{C as n}from"./ContentSection-BED6XuyO.js";import{c as s,b as i,S as r,M as l}from"./index-BDpycnKR.js";import"./firebase-Bbgk9vYU.js";import"./ui-8oM1u8yD.js";import"./gsap-BYJNJUll.js";const d=()=>{const d={title:"The Importance of Exhibition Booth Design",paragraphs:["Your exhibition booth isn’t just a display, it’s your first impression. In a busy exhibition hall, hundreds of brands are competing for attention. What makes people stop at your booth is design that connects instantly.",e.jsxs(e.Fragment,{children:["A well-designed booth doesn’t just attract visitors; it keeps them engaged. It builds trust, sparks curiosity, and gives people a reason to remember your brand. At"," ",e.jsx("span",{className:"text-bold underline main-color",children:"Sham Marianas F.Z.C"}),", we design booths that balance creativity and clarity, so your space feels open, inviting, and aligned with your brand identity."]}),"When your booth feels well-designed, your audience feels confident about your brand. That’s the power of design done right, it turns curiosity into connection, and visitors into potential clients.","From sketch to setup, we handle everything so you can focus on your event while we bring your booth to life."],image:"/assets/imgs/Booth/Booth1.png"},h={title:"Designed for the Modern Brand",paragraphs:["In today’s fast-moving world of trade shows and expos, standing out is essential. Visitors don’t just look for flashy visuals, they look for experiences. Your booth should feel alive, reflect your brand’s purpose, and create a lasting emotional impact.","That’s where we come in. Our exhibition booth design services are made for brands that want to be seen, heard, and remembered. We keep every design modern, clean, and easy to explore. Whether you want a minimalist setup or an interactive digital display, our team tailors each detail to fit your goals.","We also make sure your booth feels comfortable and functional. The flow of space, lighting, materials, and colors, all are thoughtfully chosen to create a setting where people naturally want to step in and engage.",e.jsxs(e.Fragment,{children:["At ",e.jsx("span",{className:"text-bold underline main-color",children:"Sham Marianas F.Z.C"}),", we believe design isn’t about decoration, it’s about communication. Every booth we build is designed to tell your story visually, consistently, and effectively."]})],image:"/assets/imgs/Booth/Booth2.png"},u=[{question:"How do you design a booth that fits my brand?",answer:"We begin with a clear understanding of your brand, audience, and goals. Then we create a design plan that matches your visual identity, theme, and event purpose."},{question:"Can you handle the full setup and management?",answer:"Yes. We take care of everything from concept, 3D modeling, and fabrication to setup and on-site support, so you can focus on your presentation and audience."},{question:"How long does it take to complete a project?",answer:"Most booth designs take around 3-6 weeks, depending on the size, theme, and complexity of the setup."},{question:"What makes your booth designs stand out?",answer:"We design booths that are creative, practical, and purpose-driven. Every booth tells a story, connects emotionally, and reflects your brand’s personality."},{question:"How can I get started?",answer:e.jsxs(e.Fragment,{children:["Simply contact  ",e.jsx("span",{className:"text-bold underline main-color",children:"Sham Marianas F.Z.C"}),", through our website or message our team directly. We’ll schedule a quick consultation to understand your vision and start designing your booth."]})}];return e.jsxs(e.Fragment,{children:[e.jsx(s,{type:"service",data:i.boothDesign}),e.jsx(r,{...i.boothDesign}),e.jsx(t,{title:"Exhibition ",highlightedText:"Booth",backgroundImage:"/assets/imgs/background/bg1.jpg",overlayDark:"8"}),e.jsx(o,{title:"Exhibition Booth Design",highlightedWords:["That Attracts and Connects"],customClass:"intro-webdev-section",paragraphs:[e.jsxs(e.Fragment,{children:["At"," ",e.jsx("span",{className:"text-bold text-left underline main-color",children:"Sham Marianas F.Z.C"}),", we believe your exhibition booth should do more than just look good, it should speak for your brand. Every event is an opportunity to make people stop, notice, and remember who you are. That’s exactly what we help you do."]}),"Whether you’re a new brand stepping into the spotlight or an established business preparing for your next big event, we create exhibition booth designs that make your presence unforgettable. From concept and structure to lighting and visuals, every detail is designed to draw attention and tell your brand’s story with confidence and style."],listItems:["Custom Booth Design & Fabrication","3D Booth Visualization & Layout Planning","Brand-Themed Booth Concepts","Digital Displays, Signage & Lighting Setup","Flooring, Print Collateral & Accessories","Installation, Management & On-Site Support"],imageSrc:"/assets/imgs/Booth/Booth.png",imageAlt:"Intro booth"}),e.jsx(n,{sectionOne:d,sectionTwo:h}),e.jsx("div",{className:"bord-bottom-grd pb-40 pt-40 ontop"}),e.jsx(a,{title:"Frequently Asked Questions",faqs:u,imageSrc:"/assets/imgs/FAQ.png"}),";",e.jsx(l,{})]})};export{d as default};
